questionText:
Voici un extrait de code. Quelle ligne permettra de récupérer le token JWT stocké dans le store d'authentification ?

<pre style='background:#2d2d2d; color:#f8f8f2; padding:8px; border-radius:4px;'>
const connectWebSocket = () => {
  // Ligne A
  const token = useAuthStore.getState().token;

  // Ligne B
  const token = useAuthStore(state => state.token);

  // Ligne C
  const token = authStore.token;

  // Ligne D
  const token = useSelector(state => state.auth.token);
};
</pre>

